local AnnealingLehrMaker = {}
local PRODUCTS = {
    simple_brick_annealing_lehr = { name = "Preprosta opečna ohlajevalna peč", brickCost = 3, clayCost = 2, ironCost = 1, time = 6, cost = 220, science = 22, happiness = 1, description = "Preprosta opečna ohlajevalna peč za ohlajanje stekla." },
    iron_reinforced_lehr = { name = "Železnookrepljena ohlajevalna peč", brickCost = 3, ironCost = 2, clayCost = 2, time = 9, cost = 520, science = 35, happiness = 2, prestige = 2, description = "Železnookrepljena ohlajevalna peč za trgovce." },
    silver_banded_lehr = { name = "Srebrnopasna ohlajevalna peč", brickCost = 3, silverCost = 1, ironCost = 2, clayCost = 2, time = 13, cost = 1200, science = 50, happiness = 2, prestige = 6, description = "Srebrnopasna ohlajevalna peč za plemiče." },
    gold_trimmed_lehr = { name = "Zlatookrasna ohlajevalna peč", brickCost = 3, goldCost = 1, silverCost = 1, ironCost = 2, clayCost = 2, time = 17, cost = 2700, science = 65, happiness = 3, prestige = 14, description = "Zlatookrasna ohlajevalna peč za visoke plemiče." },
    jewel_set_lehr = { name = "Draguljasta ohlajevalna peč", brickCost = 3, goldCost = 1, silverCost = 1, ironCost = 2, clayCost = 2, jewelCost = 1, time = 21, cost = 5800, science = 80, happiness = 5, prestige = 27, description = "Ohlajevalna peč z draguljem za visoko plemstvo." },
    royal_grand_annealing_lehr = { name = "Kraljevski veliki ohlajevalna peč", brickCost = 5, goldCost = 2, silverCost = 2, ironCost = 2, clayCost = 2, jewelCost = 2, pearlCost = 2, time = 28, cost = 12000, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska ohlajevalna peč z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    lehr_workshop = { name = "Ohlajevalna delavnica", cost = { gold = 300, wood = 140, stone = 180, brick = 8, clay = 6 }, upkeep = 7, qualityBonus = 5 },
    glassworks_loft = { name = "Steklarska podstrešje", cost = { gold = 1100, wood = 320, stone = 320, silver = 6, iron = 6 }, upkeep = 26, qualityBonus = 18 },
    master_lehr_atelier = { name = "Mojstrski ohlajevalni atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_glassworks_palace = { name = "Kraljevska steklarska palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
AnnealingLehrMaker.brickStock = 18; AnnealingLehrMaker.clayStock = 12; AnnealingLehrMaker.ironStock = 12; AnnealingLehrMaker.silverStock = 6; AnnealingLehrMaker.goldStock = 6; AnnealingLehrMaker.jewelStock = 4; AnnealingLehrMaker.pearlStock = 4
AnnealingLehrMaker.productStock = {}; AnnealingLehrMaker.buildings = {}; AnnealingLehrMaker.maker = nil; AnnealingLehrMaker.activeMaking = {}; AnnealingLehrMaker.totalProducts = 0; AnnealingLehrMaker.dayTimer = 0
function AnnealingLehrMaker.init() AnnealingLehrMaker.brickStock=18; AnnealingLehrMaker.clayStock=12; AnnealingLehrMaker.ironStock=12; AnnealingLehrMaker.silverStock=6; AnnealingLehrMaker.goldStock=6; AnnealingLehrMaker.jewelStock=4; AnnealingLehrMaker.pearlStock=4; AnnealingLehrMaker.productStock={}; AnnealingLehrMaker.buildings={}; AnnealingLehrMaker.maker=nil; AnnealingLehrMaker.activeMaking={}; AnnealingLehrMaker.totalProducts=0; AnnealingLehrMaker.dayTimer=0; print("[AnnealingLehrMaker] Royal Annealing Lehr Maker System initialized (6 products, 4 buildings)") end
function AnnealingLehrMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AnnealingLehrMaker.maker={name=n or ("Ohlajevalni pečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ohlajevalni pečar najet: %s (spretnost: %d)",AnnealingLehrMaker.maker.name,s),"success") end; return true end
function AnnealingLehrMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AnnealingLehrMaker.build(id) local ok,e=AnnealingLehrMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AnnealingLehrMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AnnealingLehrMaker.getQualityBonus() local b=0; for _,bd in ipairs(AnnealingLehrMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AnnealingLehrMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brickCost and AnnealingLehrMaker.brickStock<(d.brickCost or 0) then return false,"Premalo opek" end; if d.clayCost and AnnealingLehrMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.ironCost and AnnealingLehrMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and AnnealingLehrMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AnnealingLehrMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AnnealingLehrMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AnnealingLehrMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AnnealingLehrMaker.buildings==0 then return false,"Potrebna ohlajevalna delavnica" end; if not AnnealingLehrMaker.maker then return false,"Potreben ohlajevalni pečar" end; return true end
function AnnealingLehrMaker.make(pt,qty) qty=qty or 1; local ok,e=AnnealingLehrMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brickCost then AnnealingLehrMaker.brickStock=AnnealingLehrMaker.brickStock-d.brickCost*qty end; if d.clayCost then AnnealingLehrMaker.clayStock=AnnealingLehrMaker.clayStock-d.clayCost*qty end; if d.ironCost then AnnealingLehrMaker.ironStock=AnnealingLehrMaker.ironStock-d.ironCost*qty end; if d.silverCost then AnnealingLehrMaker.silverStock=AnnealingLehrMaker.silverStock-d.silverCost*qty end; if d.goldCost then AnnealingLehrMaker.goldStock=AnnealingLehrMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AnnealingLehrMaker.jewelStock=AnnealingLehrMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AnnealingLehrMaker.pearlStock=AnnealingLehrMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AnnealingLehrMaker.maker then t=math.max(1,t-math.floor(AnnealingLehrMaker.maker.skill/12)) end; table.insert(AnnealingLehrMaker.activeMaking,{id="annealinglehr_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AnnealingLehrMaker.completeMaking(m) local q=1.0+(AnnealingLehrMaker.getQualityBonus()/100); if AnnealingLehrMaker.maker then q=q+(AnnealingLehrMaker.maker.skill/140) end; q=math.min(2.5,q); AnnealingLehrMaker.productStock[m.productType]=(AnnealingLehrMaker.productStock[m.productType] or 0)+m.quantity; AnnealingLehrMaker.totalProducts=AnnealingLehrMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AnnealingLehrMaker.maker then AnnealingLehrMaker.maker.itemsMade=AnnealingLehrMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AnnealingLehrMaker.maker.skill=math.min(100,AnnealingLehrMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ohlajevalna peč izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"annealinglehr.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function AnnealingLehrMaker.update(dt) if not _G.state then return end; AnnealingLehrMaker.dayTimer=AnnealingLehrMaker.dayTimer+dt; if AnnealingLehrMaker.dayTimer>=30 then AnnealingLehrMaker.dayTimer=0; for i=#AnnealingLehrMaker.activeMaking,1,-1 do local m=AnnealingLehrMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AnnealingLehrMaker.completeMaking(m); table.remove(AnnealingLehrMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AnnealingLehrMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AnnealingLehrMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AnnealingLehrMaker.getStats() return {brickStock=AnnealingLehrMaker.brickStock,clayStock=AnnealingLehrMaker.clayStock,ironStock=AnnealingLehrMaker.ironStock,silverStock=AnnealingLehrMaker.silverStock,goldStock=AnnealingLehrMaker.goldStock,jewelStock=AnnealingLehrMaker.jewelStock,pearlStock=AnnealingLehrMaker.pearlStock,productStock=AnnealingLehrMaker.productStock,numBuildings=#AnnealingLehrMaker.buildings,hasMaker=AnnealingLehrMaker.maker~=nil,makerName=AnnealingLehrMaker.maker and AnnealingLehrMaker.maker.name or "—",makerSkill=AnnealingLehrMaker.maker and AnnealingLehrMaker.maker.skill or 0,activeMaking=#AnnealingLehrMaker.activeMaking,totalProducts=AnnealingLehrMaker.totalProducts} end
return AnnealingLehrMaker
